        self.failures = Counter()

    def record(self, provider: str, *, ok: bool, elapsed_ms: int, route_reason: str) -> None:
        event = {
            "provider": provider,
            "ok": bool(ok),
            "elapsed_ms": int(elapsed_ms),
            "route_reason": route_reason,
