            complexity = max(complexity, 9)
        if mode == "coding":
            coding = 10
        if mode == "fast":
            speed, cost = 10, 9
        if mode == "autopilot":
            complexity = max(complexity, 7)
            risk = max(risk, 5)

        reason = "default general task"
        if privacy >= 8:
            reason = "privacy/local-only requirement"
        elif coding >= 8:
            reason = "software-engineering task"
        elif complexity >= 8:
            reason = "high-complexity reasoning task"
        elif speed >= 8:
